// Sanctioned bridges between aesthetics: 2 = strong, 1 = soft. Unlisted pairs do not bridge.
const BRIDGES_RAW = {
  'coquette|fairy': 2, 'coquette|sleaze': 2, 'fairy|sleaze': 2, 'siren|quiet': 2, 'quiet|clean': 2, 'ballet|clean': 2, 'ballet|coquette': 2,
  'chrome|gorp': 2, 'chrome|y2k': 2, 'sleaze|y2k': 2, 'blokette|y2k': 2, 'boho|fairy': 2, 'academia|siren': 1,
  'mob|siren': 1, 'mob|quiet': 1, 'boho|sleaze': 1, 'academia|fairy': 1, 'chrome|siren': 1, 'ballet|gorp': 1,
  'coquette|academia': 1, 'blokette|coquette': 1, 'blokette|clean': 1, 'blokette|gorp': 1, 'academia|quiet': 2,
  'clean|y2k': 1, 'boho|coquette': 1, 'mob|sleaze': 1, 'siren|sleaze': 1, 'chrome|clean': 1, 'coquette|siren': 1,
};
export const BRIDGES = Object.fromEntries(Object.entries(BRIDGES_RAW).map(([k, v]) => [k.split('|').sort().join('|'), v]));
export const bridgeOf = (a, b) => BRIDGES[[a, b].sort().join('|')] || 0;

