const items = [];
function def(o) {
  const it = {
    rarity: 'core', source: 'atelier', price: 240, formality: 2, weight: 2, texture: 'cotton', shine: 0, volume: 0,
    sharp: false, statement: 0, aesthetics: {}, metal: null, ...o,
  };
  if (!it.colors) it.colors = [it.color, it.color2].filter(Boolean);
  items.push(it);
  return it;
}

