/* ------------------------------ HAIR (part of the look) ------------------------------ */
// Four styles come with the game; the rest are bought with credits or arrive with a set.
const HAIR_STARTERS = new Set(['longWavy', 'sleekBun', 'bob', 'halfUp']);
const HAIR_PRICE = { slickPony: 260, frenchBob: 320, longStraight: 300, curly: 300, braids: 340, wolfCut: 420, spaceBuns: 280, pixie: 380, lowBun: 300 };
for (const [style, hm] of Object.entries(HAIR_META)) {
  const id = 'hr_' + style.replace(/[A-Z]/g, (m) => '_' + m.toLowerCase());
  const starter = HAIR_STARTERS.has(style);
  def({ id, slot: 'hair', name: hm.name, house: 'NUL', color: null, render: { kind: 'hair', style }, formality: hm.formality, weight: 1, texture: 'hair', sharp: !!hm.sharp, aesthetics: hm.aes, source: starter ? 'starter' : 'atelier', price: starter ? 0 : HAIR_PRICE[style] || 300, isHair: true, desc: starter ? 'In the drawer from day one.' : 'A cut and a finish. Hair carries the dress code as much as the shoe.' });
}

// Handmade signature pieces + the procedural catalogue (bases × colourways × materials × prints) + sets.
const built = buildCatalog(items);
export const CATALOG = built.items;
export const SETS = built.sets;
export const SET_BY_ID = Object.fromEntries(built.sets.map((s) => [s.id, s]));
export const BY_ID = Object.fromEntries(CATALOG.map((i) => [i.id, i]));
export const STARTER_IDS = CATALOG.filter((i) => i.source === 'starter').map((i) => i.id);
export const BY_SLOT = CATALOG.reduce((m, i) => ((m[i.slot] ||= []).push(i), m), {});
